import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, title TEXT, content TEXT,
        owner TEXT, classification TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, user TEXT, scope TEXT)''')
    db.commit()
    db.close()

def authenticate(req):
    key = req.headers.get('X-Api-Key', '')
    if not key:
        return None
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT user, scope FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    return dict(row) if row else None

@app.route('/api/v2/documents/search', methods=['POST'])
def search_documents():
    auth = authenticate(request)
    if not auth:
        return jsonify({'error': 'unauthorized'}), 401

    body = request.get_json(force=True)
    filters = body.get('filters', {})

    # Build query with owner scope restriction
    base_query = "SELECT id, title, classification FROM documents WHERE owner = '" + auth['user'] + "'"

    # Apply optional classification filter
    classification = filters.get('classification', '')
    if classification:
        # Validate against known values
        allowed = ['PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED']
        if classification.upper() not in allowed:
            return jsonify({'error': 'invalid classification'}), 400
        base_query += " AND classification = '" + classification + "'"

    # Apply title search - vulnerable to injection via title_contains
    title_search = filters.get('title_contains', '')
    if title_search:
        base_query += " AND title LIKE '%" + title_search + "%'"

    # Apply date range if present
    date_from = filters.get('date_from', '')
    if date_from:
        base_query += " AND created_at >= '" + date_from + "'"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v2/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    auth = authenticate(request)
    if not auth:
        return jsonify({'error': 'unauthorized'}), 401
    db = get_db()
    row = db.execute('SELECT * FROM documents WHERE id = ? AND owner = ?', (doc_id, auth['user'])).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
